set-variable.value:
@{
        var jwt = (Jwt)context.Variables["validatedToken"];
        if (jwt == null) { return "unknown"; }
        if (jwt.Claims.ContainsKey("azp")) { return jwt.Claims["azp"].FirstOrDefault() ?? "unknown"; }
        if (jwt.Claims.ContainsKey("appid")) { return jwt.Claims["appid"].FirstOrDefault() ?? "unknown"; }
        return "unknown";
    }

@{
        var jwt = (Jwt)context.Variables["validatedToken"];
        if (jwt == null) { return "unknown"; }
        if (jwt.Claims.ContainsKey("oid")) { return jwt.Claims["oid"].FirstOrDefault() ?? "unknown"; }
        return "unknown";
    }

@{
        var jwt = (Jwt)context.Variables["validatedToken"];
        if (jwt == null) { return ""; }
        if (jwt.Claims.ContainsKey("sub") && jwt.Claims.ContainsKey("scp") && jwt.Claims.ContainsKey("oid")) { return jwt.Claims["oid"].FirstOrDefault() ?? ""; }
        return "";
    }

@{
        if (string.IsNullOrEmpty((string)context.Variables["validatedUserOid"])) { return ""; }
        var jwt = (Jwt)context.Variables["validatedToken"];
        return jwt.Claims.ContainsKey("name") ? jwt.Claims["name"].FirstOrDefault() ?? "" : "";
    }

@{
        if (string.IsNullOrEmpty((string)context.Variables["validatedUserOid"])) { return ""; }
        var jwt = (Jwt)context.Variables["validatedToken"];
        if (jwt.Claims.ContainsKey("preferred_username")) { return jwt.Claims["preferred_username"].FirstOrDefault() ?? ""; }
        if (jwt.Claims.ContainsKey("upn")) { return jwt.Claims["upn"].FirstOrDefault() ?? ""; }
        if (jwt.Claims.ContainsKey("email")) { return jwt.Claims["email"].FirstOrDefault() ?? ""; }
        return "";
    }

@{
        if (string.IsNullOrEmpty((string)context.Variables["validatedUserOid"])) { return ""; }
        var jwt = (Jwt)context.Variables["validatedToken"];
        return string.Join(" ", jwt.Claims["scp"]);
    }

@{
        var jwt = (Jwt)context.Variables["validatedToken"];
        if (jwt == null || !jwt.Claims.ContainsKey("xms_act_fct")) { return ""; }
        return string.Join(",", jwt.Claims["xms_act_fct"]);
    }
